"use strict";
// GENERATED by build_bundle.py — do not edit. Edit src/*.js and re-run.

const ppro = require("premierepro");
const uxp = require("uxp");

// ---------- spec.js ----------
/**
 * Load and validate an edit_spec.json package (architecture §8).
 *
 * The spec is format-neutral: float-second times, media paths relative to the
 * package folder. Everything Premiere-specific happens in build.js/exporter.js.
 */


/** Minimal structural validation — fail loudly before touching the project. */
function validateSpec(spec) {
  const problems = [];
  if (!spec || typeof spec !== "object") problems.push("root is not an object");
  if (!spec.project || !spec.project.fps || !spec.project.width || !spec.project.height) {
    problems.push("project.fps/width/height missing");
  }
  if (!Array.isArray(spec.media) || spec.media.length === 0) {
    problems.push("media list missing or empty");
  }
  if (!Array.isArray(spec.tracks)) problems.push("tracks list missing");
  const audio = (spec.media || []).find((m) => m.type === "audio");
  if (!audio) problems.push("no audio media entry");
  return problems;
}

/**
 * Open a folder picker rooted at the package, read edit_spec.json, and return
 * { spec, packageFolder } where packageFolder is a UXP folder entry used to
 * resolve the spec's relative media paths to native paths.
 */
async function loadSpecInteractive() {
  const fs = uxp.storage.localFileSystem;
  const specFile = await fs.getFileForOpening({ types: ["json"] });
  if (!specFile) return null;

  const spec = JSON.parse(await specFile.read());
  const problems = validateSpec(spec);
  if (problems.length) {
    throw new Error("edit_spec.json is not usable: " + problems.join("; "));
  }

  // The package folder is the spec file's parent; relative paths resolve
  // against it. UXP file entries expose the OS path via nativePath.
  const packageNativePath = specFile.nativePath.replace(/[\\/][^\\/]+$/, "");
  return { spec, packageNativePath };
}

/** Resolve a spec-relative path ("audio/x.m4a") to a native OS path. */
function resolvePath(packageNativePath, relPath) {
  const sep = packageNativePath.includes("\\") ? "\\" : "/";
  return packageNativePath + sep + relPath.split("/").join(sep);
}

/** Does a native path exist? Used to probe for optional package assets. */
async function fileExists(nativePath) {
  try {
    await uxp.storage.localFileSystem.getEntryWithUrl("file:" + nativePath);
    return true;
  } catch (error) {
    return false;
  }
}

/** One-line human summary for the panel UI. */
function summarize(spec) {
  const captions = spec.tracks.find((t) => t.kind === "captions");
  const graphics = spec.tracks.find((t) => t.kind === "graphics");
  const overlays = graphics ? graphics.items.filter((i) => i.type === "ayah_overlay") : [];
  const highlights = graphics ? graphics.items.filter((i) => i.type === "word_highlight") : [];
  const keyframes = highlights.reduce((n, i) => n + (i.keyframes || []).length, 0);
  return [
    `mode: ${(spec.meta && spec.meta.mode) || "?"}`,
    `project: ${spec.project.width}x${spec.project.height} @ ${spec.project.fps} fps`,
    `media: ${spec.media.length}  cues: ${captions ? captions.cues.length : 0}`,
    `overlays: ${overlays.length}  highlight keyframes: ${keyframes}`,
    `warnings from emitter: ${(spec.meta && (spec.meta.validation_warnings || []).length) || 0}`,
  ].join("\n");
}

// ---------- build.js ----------
/**
 * Build the editable sequence from the edit-spec (architecture §9).
 *
 * Signatures below follow the published Premiere 25.6 API reference (25.6 is the
 * minimum version supporting UXP at all, and is what we target):
 *   - project.importFiles(paths, suppressUI, targetBin, asNumberedStills)
 *   - project.createSequenceFromMedia(name, clipProjectItems, targetBin)
 *   - ppro.SequenceEditor.getEditor(seq).createOverwriteItemAction(item, time, vIdx, aIdx)
 *   - ppro.TickTime.createWithSeconds(seconds)
 *   - ppro.Markers.getMarkers(sequence) + createAddMarkerAction(...) — markerType
 *     is a plain string ("Comment"); there is no Constants.MarkerType enum.
 *   - videoClipTrackItem.createSetEndAction(tickTime) to trim a placed still.
 *   - project.lockedAccess(cb) / project.executeTransaction(cb, name)
 *
 * Still missing from UXP entirely (not a bug here):
 *   - caption-cue creation — caption tracks are READ-ONLY through 26.3, see
 *     captions.js for the SRT fallback;
 *   - the highlight_v1 MOGRT that word_highlight keyframes would drive.
 */


/** Run one prepared action inside a locked transaction (Adobe sample pattern). */
function runTransaction(project, name, buildActions) {
  project.lockedAccess(() => {
    project.executeTransaction((compoundAction) => {
      for (const action of buildActions()) {
        compoundAction.addAction(action);
      }
    }, name);
  });
}

/** Find a project item by file name. getRootItem() is async and returns a FolderItem. */
async function findProjectItemByName(project, name) {
  const root = await project.getRootItem();
  const stack = [root];
  while (stack.length) {
    const folder = stack.pop();
    const items = await folder.getItems();
    for (const item of items) {
      if (item.name === name) return item;
      if (typeof item.getItems === "function") stack.push(item);
    }
  }
  return null;
}

/** Import every media path in the spec plus all overlay PNG assets. */
async function importPackageMedia(project, spec, packageNativePath, log) {
  const paths = [];
  for (const media of spec.media) paths.push(resolvePath(packageNativePath, media.path));
  const graphics = spec.tracks.find((t) => t.kind === "graphics");
  const seen = new Set();
  for (const item of (graphics ? graphics.items : [])) {
    if (item.type === "ayah_overlay" && item.asset && !seen.has(item.asset)) {
      seen.add(item.asset);
      paths.push(resolvePath(packageNativePath, item.asset));
    }
  }
  log(`Importing ${paths.length} file(s)…`);
  const root = await project.getRootItem();
  const ok = await project.importFiles(
    paths,
    /* suppressUI */ true,
    /* targetBin */ root,
    /* asNumberedStills */ false
  );
  if (!ok) throw new Error("importFiles reported failure");
  return paths;
}

/**
 * Create the sequence. Preferred: createSequenceFromMedia with the reference
 * render, which conforms the sequence to the exact render settings
 * (width/height/fps) without needing a .sqpreset on disk. Fallback: default
 * preset + a loud warning to fix settings by hand.
 */
async function createSequence(project, spec, log) {
  const videoMedia = spec.media.find((m) => m.type === "video");
  const name = "Qalun " + ((spec.meta && spec.meta.created_from && spec.meta.created_from.audio) || "sequence");
  if (videoMedia) {
    const refItem = await findProjectItemByName(project, baseName(videoMedia.path));
    if (refItem) {
      const clipItem = castClipProjectItem(refItem);
      const root = await project.getRootItem();
      const sequence = await project.createSequenceFromMedia(name, [clipItem], root);
      log("Sequence created from the reference render (settings conformed).", "ok");
      return sequence;
    }
  }
  log(
    "No reference render found — created a default-preset sequence; verify " +
      `${spec.project.width}x${spec.project.height}@${spec.project.fps} manually.`,
    "warn"
  );
  return project.createSequence(name);
}

/** ClipProjectItem.cast narrows a ProjectItem; feature-detected for safety. */
function castClipProjectItem(item) {
  if (ppro.ClipProjectItem && typeof ppro.ClipProjectItem.cast === "function") {
    return ppro.ClipProjectItem.cast(item);
  }
  return item;
}

/** Place the job audio on A1 at 0 (the sequence-from-media path already has it). */
async function placeAudio(project, sequence, spec, log) {
  const audioMedia = spec.media.find((m) => m.type === "audio");
  const item = await findProjectItemByName(project, baseName(audioMedia.path));
  if (!item) throw new Error(`Audio '${audioMedia.path}' not found after import`);
  const editor = ppro.SequenceEditor.getEditor(sequence);
  runTransaction(project, "Qalun: place audio", () => [
    editor.createOverwriteItemAction(
      castClipProjectItem(item),
      ppro.TickTime.createWithSeconds(0),
      0,
      0
    ),
  ]);
  log("Audio placed on A1 at 0.", "ok");
}

/**
 * Place ayah overlays. When the MOGRT from the spec exists inside the package
 * (mogrts/<name>.mogrt) instantiate it; otherwise fall back to the interim
 * transparent PNG on V2 (V1 holds the reference render).
 */
async function placeOverlays(project, sequence, spec, packageNativePath, log) {
  const graphics = spec.tracks.find((t) => t.kind === "graphics");
  if (!graphics) return;
  const overlays = graphics.items.filter((i) => i.type === "ayah_overlay");
  const editor = ppro.SequenceEditor.getEditor(sequence);

  let placed = 0;
  let untrimmed = 0;
  for (const overlay of overlays) {
    const startTime = ppro.TickTime.createWithSeconds(overlay.in);
    const mogrtPath = resolvePath(packageNativePath, `mogrts/${overlay.mogrt}.mogrt`);
    if (await fileExists(mogrtPath)) {
      // §9 target state: MOGRT with editable style, locked text.
      editor.insertMogrtFromPath(mogrtPath, startTime, 1, 1);
      placed++;
      continue;
    }
    const item = await findProjectItemByName(project, baseName(overlay.asset));
    if (!item) {
      log(`Overlay asset missing in project: ${overlay.asset}`, "warn");
      continue;
    }
    runTransaction(project, `Qalun: overlay ${overlay.ref}`, () => [
      editor.createOverwriteItemAction(castClipProjectItem(item), startTime, 1, 0),
    ]);
    if (!(await trimOverlayToSpec(project, sequence, overlay, log))) untrimmed++;
    placed++;
  }
  log(`Placed ${placed}/${overlays.length} ayah overlay(s) on V2.`, placed === overlays.length ? "ok" : "warn");
  if (untrimmed) {
    log(`${untrimmed} overlay(s) kept Premiere's default still duration — trim by hand.`, "warn");
  }
}

/**
 * Trim a placed still to its card window. Without this the PNG keeps Premiere's
 * default still duration (~5 s) rather than running to overlay.out — for the
 * furquanTra7-11 package that would end the ayah card at ~9 s instead of ~101 s.
 * Defensive: a failure here costs one manual trim, not the whole build.
 */
async function trimOverlayToSpec(project, sequence, overlay, log) {
  try {
    const track = await sequence.getVideoTrack(1);
    if (!track) return false;
    const items = await track.getTrackItems(ppro.Constants.TrackItemType.CLIP, false);
    if (!items || !items.length) return false;

    // The clip we just overwrote is the one starting at overlay.in.
    let target = null;
    let closest = Infinity;
    for (const item of items) {
      const start = await item.getStartTime();
      const delta = Math.abs(Number(start.seconds) - overlay.in);
      if (delta < closest) {
        closest = delta;
        target = item;
      }
    }
    if (!target || typeof target.createSetEndAction !== "function") return false;

    runTransaction(project, `Qalun: trim overlay ${overlay.ref}`, () => [
      target.createSetEndAction(ppro.TickTime.createWithSeconds(overlay.out)),
    ]);
    return true;
  } catch (error) {
    log(`Could not trim overlay ${overlay.ref} (${error.message}).`, "warn");
    return false;
  }
}

/**
 * Word-highlight keyframes. Target state (§9): drive the highlight_v1 MOGRT's
 * position/progress param per keyframe. Until that MOGRT is authored there is
 * no numeric param to key, so this logs the intent and — as a proof of the
 * keyframe pipeline — keys Opacity on the overlay clip when reachable.
 */
async function applyHighlightKeyframes(project, sequence, spec, log) {
  const graphics = spec.tracks.find((t) => t.kind === "graphics");
  if (!graphics) return;
  const highlights = graphics.items.filter((i) => i.type === "word_highlight");
  const total = highlights.reduce((n, i) => n + (i.keyframes || []).length, 0);
  if (!total) return;
  log(
    `word_highlight: ${total} keyframes staged for '${highlights[0].mogrt}'. ` +
      "MOGRT not authored yet — keyframes are NOT applied in this skeleton " +
      "(see README: highlight MOGRT contract).",
    "warn"
  );
  // Pipeline proof (runs when the first overlay clip is reachable):
  //   const track = await sequence.getVideoTrack(1);
  //   const clip = track.getTrackItems(ppro.Constants.TrackItemType.CLIP, false)[0];
  //   const chain = await clip.getComponentChain();
  //   ...find Opacity componentParam → createKeyframe/createAddKeyframeAction
  // Left commented until the MOGRT lands so the walking skeleton never fights
  // a designer's manual opacity work.
}

/** One sequence marker named "surah:ayah" at each ayah start (cue refs). */
async function addAyahMarkers(project, sequence, spec, log) {
  const captions = spec.tracks.find((t) => t.kind === "captions");
  if (!captions) return;
  const markers = await ppro.Markers.getMarkers(sequence);
  const cuesWithRefs = captions.cues.filter((cue) => cue.ref);
  runTransaction(project, "Qalun: ayah markers", () =>
    cuesWithRefs.map((cue) =>
      markers.createAddMarkerAction(
        cue.ref,
        "Comment", // markerType is a plain string; there is no Constants.MarkerType enum
        ppro.TickTime.createWithSeconds(cue.in),
        ppro.TickTime.createWithSeconds(Math.max(0, cue.out - cue.in)),
        cue.text || ""
      )
    )
  );
  log(`Added ${cuesWithRefs.length} ayah marker(s).`, "ok");
}

function baseName(relPath) {
  return relPath.split("/").pop();
}

// ---------- captions.js ----------
/**
 * Caption track from the spec's cue list (editable text — the whole point of
 * §9's "scripting, not export formats").
 *
 * Reality check against @adobe/premierepro 26.3.0: caption tracks are
 * READ-ONLY in UXP today — Sequence exposes getCaptionTrackCount() and
 * getCaptionTrack(i), and CaptionTrack has no cue-creation methods. The
 * ExtendScript API had Sequence.createCaptionTrack(projectItem, …) fed by an
 * imported SRT/caption project item, but ExtendScript sunsets Sept 2026 and
 * is not a base to build on.
 *
 * Strategy, in order:
 *   1. Feature-detect a createCaptionTrack on the UXP sequence object (newer
 *      builds may add it) and feed it the imported SRT project item.
 *   2. Fallback: import the package's SRT (UTF-8 BOM, RTL-safe) into the
 *      project bin and tell the user to drop it on a caption track — one
 *      manual drag, captions stay fully editable afterwards.
 */


async function buildCaptions(project, sequence, spec, packageNativePath, log) {
  const captions = spec.tracks.find((t) => t.kind === "captions");
  if (!captions || !captions.cues || !captions.cues.length) {
    log("No caption cues in spec; skipping captions.");
    return;
  }

  const srtNative = resolvePath(packageNativePath, captions.srt);
  const root = await project.getRootItem();
  const imported = await project.importFiles([srtNative], true, root, false);
  if (!imported) {
    log(`Could not import caption SRT '${captions.srt}'.`, "error");
    return;
  }

  if (typeof sequence.createCaptionTrack === "function") {
    // Not in any shipped UXP build (caption tracks are read-only through 26.3);
    // feature-detected so the panel picks it up the moment Adobe ships it.
    const srtItem = await findProjectItemByName(project, captions.srt.split("/").pop());
    try {
      await sequence.createCaptionTrack(srtItem);
      log(`Caption track created from ${captions.srt} (${captions.cues.length} cues).`, "ok");
      return;
    } catch (error) {
      log(`createCaptionTrack failed (${error.message}); falling back.`, "warn");
    }
  }

  log(
    `Caption cues imported as '${captions.srt}' in the project bin. UXP cannot ` +
      "create caption tracks yet (read-only caption API as of 26.3) — drag the " +
      "SRT onto the sequence once; Premiere converts it to an editable caption track.",
    "warn"
  );
}

// ---------- exporter.js ----------
/**
 * Save the editable project and trigger the AME export (§9: both outputs come
 * from the same project, so the MP4 always matches the .prproj exactly).
 *
 * Premiere 25.6 API reference:
 *   EncoderManager.getManager(), manager.isAMEInstalled (property)
 *   manager.exportSequence(sequence, exportType, outputFile, presetFile, exportFull)
 *     — presetFile (.epr) is REQUIRED; there is no 3-arg overload.
 *   Constants.ExportType.{QUEUE_TO_AME, QUEUE_TO_APP, IMMEDIATELY}
 *   manager.launchEncoder() is 26.3+ ONLY — feature-detect before calling.
 */


const PRESET_REL = "export/qalun_h264.epr";

async function saveProjectIntoPackage(project, packageNativePath, log) {
  const target = resolvePath(packageNativePath, "project.prproj");
  const ok = await project.saveAs(target);
  if (!ok) throw new Error("project.saveAs failed");
  log(`Saved editable project: ${target}`, "ok");
  return target;
}

async function exportViaAME(project, sequence, spec, packageNativePath, log) {
  const manager = ppro.EncoderManager.getManager();
  const output = resolvePath(packageNativePath, "video/export_from_premiere.mp4");
  const preset = resolvePath(packageNativePath, PRESET_REL);

  // 25.6 requires a preset file. We ship none, and passing a bogus path fails
  // deeper in AME with an opaque error — so bail out with instructions instead.
  if (!(await fileExists(preset))) {
    log(
      `No export preset at '${PRESET_REL}'. Premiere 25.6 requires one for a ` +
        "scripted export. Either create it once (File → Export → Media → H.264 → " +
        `Save Preset → save into the package as ${PRESET_REL}) and click again, ` +
        "or just export by hand with File → Export → Media.",
      "warn"
    );
    return;
  }

  if (manager.isAMEInstalled) {
    const queued = await manager.exportSequence(
      sequence,
      ppro.Constants.ExportType.QUEUE_TO_AME,
      output,
      preset,
      /* exportFull */ true
    );
    if (queued) {
      if (typeof manager.launchEncoder === "function") {
        await manager.launchEncoder(); // 26.3+ only
        log(`Export queued in Adobe Media Encoder → ${output}`, "ok");
      } else {
        log(
          `Export queued → ${output}. Switch to Adobe Media Encoder and press ` +
            "Play to render (launchEncoder needs Premiere 26.3+).",
          "warn"
        );
      }
      return;
    }
    log("Queueing to AME failed; trying in-app export.", "warn");
  } else {
    log("AME not installed; using in-app export.", "warn");
  }

  // Fallback 1: Premiere's own export queue (no AME needed, blocks the app).
  const done = await manager.exportSequence(
    sequence,
    ppro.Constants.ExportType.IMMEDIATELY,
    output,
    preset,
    /* exportFull */ true
  );
  if (done) {
    log(`Exported in-app → ${output}`, "ok");
    return;
  }

  // Fallback 2 (§9): an AME watch folder. Nothing to automate from here —
  // the user points a watch folder at the package and drops project.prproj in.
  log(
    "Automatic export failed. Fallback: configure an AME watch folder on the " +
      "package directory and drop project.prproj into it.",
    "error"
  );
}

// Flattened: main.js expects build.* — rebuild the namespace from the top-level
// functions that build.js contributed to this bundle.
const build = {
  importPackageMedia,
  createSequence,
  placeAudio,
  placeOverlays,
  applyHighlightKeyframes,
  addAyahMarkers,
  findProjectItemByName,
};


// ---------- main.js ----------
/**
 * Panel bootstrap: wires the four buttons to the §9 pipeline
 * (read spec → import media → build sequence → captions/overlays/markers →
 * save project.prproj → AME export).
 */

// UXP's require() does no Node-style resolution: relative modules must carry
// the explicit .js extension or the panel dies at load.

const state = { spec: null, packageNativePath: null, sequence: null };

const logEl = document.getElementById("log");
function log(message, cls) {
  const line = document.createElement("div");
  if (cls) line.className = cls;
  line.textContent = message;
  logEl.appendChild(line);
  logEl.scrollTop = logEl.scrollHeight;
}

async function activeProject() {
  const project = await ppro.Project.getActiveProject();
  if (!project) throw new Error("Open (or create) a project in Premiere first.");
  return project;
}

document.getElementById("btn-load").addEventListener("click", async () => {
  try {
    const loaded = await loadSpecInteractive();
    if (!loaded) return;
    state.spec = loaded.spec;
    state.packageNativePath = loaded.packageNativePath;
    document.getElementById("spec-summary").textContent = summarize(loaded.spec);
    document.getElementById("btn-build").disabled = false;
    log(`Loaded spec from ${loaded.packageNativePath}`, "ok");
    for (const warning of (loaded.spec.meta && loaded.spec.meta.validation_warnings) || []) {
      log(`emitter warning: ${warning}`, "warn");
    }
  } catch (error) {
    log(error.message, "error");
  }
});

document.getElementById("btn-build").addEventListener("click", async () => {
  try {
    const project = await activeProject();
    const { spec, packageNativePath } = state;

    await build.importPackageMedia(project, spec, packageNativePath, log);
    state.sequence = await build.createSequence(project, spec, log);
    await build.placeAudio(project, state.sequence, spec, log);
    await build.placeOverlays(project, state.sequence, spec, packageNativePath, log);
    await build.applyHighlightKeyframes(project, state.sequence, spec, log);
    await buildCaptions(project, state.sequence, spec, packageNativePath, log);
    await build.addAyahMarkers(project, state.sequence, spec, log);

    document.getElementById("btn-save").disabled = false;
    log("Sequence built. Review, then save + export.", "ok");
  } catch (error) {
    log("Build failed: " + error.message, "error");
  }
});

document.getElementById("btn-save").addEventListener("click", async () => {
  try {
    const project = await activeProject();
    await saveProjectIntoPackage(project, state.packageNativePath, log);
    document.getElementById("btn-export").disabled = false;
  } catch (error) {
    log("Save failed: " + error.message, "error");
  }
});

document.getElementById("btn-export").addEventListener("click", async () => {
  try {
    const project = await activeProject();
    await exportViaAME(project, state.sequence, state.spec, state.packageNativePath, log);
  } catch (error) {
    log("Export failed: " + error.message, "error");
  }
});
